SELECT 
FROM rule_definition
WHERE user_id = #{userId}
  AND deleted = 0

    AND source_type = #{sourceType}


    AND action_type = #{actionType}


    AND enabled = #{enabled}


    AND (name LIKE CONCAT('%', #{keyword}, '%')
         OR description LIKE CONCAT('%', #{keyword}, '%'))

ORDER BY id DESC

SELECT COUNT(*)
FROM rule_definition
WHERE user_id = #{userId}
  AND deleted = 0
  AND name = #{name}

    AND id != #{excludeId}

